/* eslint-disable no-restricted-globals */
/**
 * CalibiAI service worker.
 *
 * Hand-written rather than generated by `next-pwa`, which is a Webpack-only
 * plugin (unmaintained since 2022) and conflicts with this app's Turbopack
 * build. This gives the same caching guarantees with zero build coupling.
 *
 * Caching strategy per resource class:
 *   - Navigations ....... network-first, falling back to the offline shell.
 *   - Build assets ...... cache-first (immutable, content-hashed under /_next/static).
 *   - CSS / JS .......... stale-while-revalidate.
 *   - Fonts ............. cache-first, long-lived.
 *   - Images / logo ..... cache-first with a bounded entry count.
 *   - API / auth ........ never cached.
 *
 * PRIVACY: authenticated HTML is deliberately never written to the cache.
 * Roadmaps, scores and community feeds are per-user, and persisting them would
 * leak one account's data to the next on a shared device.
 */

const VERSION = "v1";
const PRECACHE = `calibiai-precache-${VERSION}`;
const STATIC_CACHE = `calibiai-static-${VERSION}`;
const FONT_CACHE = `calibiai-fonts-${VERSION}`;
const IMAGE_CACHE = `calibiai-images-${VERSION}`;

const OFFLINE_URL = "/offline";

/** The minimal shell needed to render something useful with no network. */
const PRECACHE_URLS = [
  OFFLINE_URL,
  "/manifest.webmanifest",
  "/icons/icon-192.png",
  "/icons/icon-512.png",
  "/icons/apple-touch-icon.png",
  "/images/calibiai-logo.svg",
];

/** Keeps the image cache from growing without bound on long-lived installs. */
const IMAGE_CACHE_LIMIT = 60;

async function trimCache(cacheName, maxEntries) {
  const cache = await caches.open(cacheName);
  const keys = await cache.keys();
  if (keys.length <= maxEntries) return;
  await Promise.all(keys.slice(0, keys.length - maxEntries).map((key) => cache.delete(key)));
}

self.addEventListener("install", (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(PRECACHE);
      // `addAll` rejects the whole batch if any single request 404s, which
      // would leave the worker permanently uninstalled. Cache individually.
      await Promise.all(
        PRECACHE_URLS.map(async (url) => {
          try {
            const response = await fetch(new Request(url, { cache: "reload" }));
            if (response.ok) await cache.put(url, response);
          } catch {
            // A missing optional asset must never block installation.
          }
        }),
      );
      await self.skipWaiting();
    })(),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const valid = new Set([PRECACHE, STATIC_CACHE, FONT_CACHE, IMAGE_CACHE]);
      const names = await caches.keys();
      await Promise.all(names.filter((name) => !valid.has(name)).map((name) => caches.delete(name)));

      // Speeds up repeat navigations for browsers that support it.
      if (self.registration.navigationPreload) {
        await self.registration.navigationPreload.enable();
      }
      await self.clients.claim();
    })(),
  );
});

/** Lets the page trigger an immediate update instead of waiting for a reload. */
self.addEventListener("message", (event) => {
  if (event.data === "SKIP_WAITING") self.skipWaiting();
});

function isFont(request, url) {
  return request.destination === "font" || /\.(?:woff2?|ttf|otf|eot)$/i.test(url.pathname);
}

function isImage(request, url) {
  return (
    request.destination === "image" ||
    /\.(?:png|jpe?g|gif|webp|avif|svg|ico)$/i.test(url.pathname) ||
    url.pathname.startsWith("/_next/image")
  );
}

function isStaticAsset(request, url) {
  return (
    request.destination === "style" ||
    request.destination === "script" ||
    request.destination === "worker" ||
    url.pathname.startsWith("/_next/static") ||
    /\.(?:css|js)$/i.test(url.pathname)
  );
}

/** Routes that must always hit the network — dynamic, personal or mutating. */
function isNeverCached(url) {
  return (
    url.pathname.startsWith("/api/") ||
    url.pathname.startsWith("/auth/") ||
    url.pathname.startsWith("/admin") ||
    url.pathname.includes("/supabase")
  );
}

async function cacheFirst(request, cacheName, { limit } = {}) {
  const cache = await caches.open(cacheName);
  const cached = await cache.match(request);
  if (cached) return cached;

  const response = await fetch(request);
  if (response && response.ok && response.type !== "opaque") {
    await cache.put(request, response.clone());
    if (limit) void trimCache(cacheName, limit);
  }
  return response;
}

async function staleWhileRevalidate(request, cacheName) {
  const cache = await caches.open(cacheName);
  const cached = await cache.match(request);

  const network = fetch(request)
    .then((response) => {
      if (response && response.ok) void cache.put(request, response.clone());
      return response;
    })
    .catch(() => undefined);

  // Serve the cached copy instantly; refresh it in the background.
  return cached || (await network) || Response.error();
}

self.addEventListener("fetch", (event) => {
  const { request } = event;

  // Only GET is cacheable; everything else (POST server actions, auth) passes through.
  if (request.method !== "GET") return;

  const url = new URL(request.url);

  // Leave cross-origin requests (Supabase, analytics, third-party embeds) alone.
  if (url.origin !== self.location.origin) return;

  if (isNeverCached(url)) return;

  // ── Navigations: network-first with an offline fallback ──────────────────
  if (request.mode === "navigate") {
    event.respondWith(
      (async () => {
        try {
          const preloaded = await event.preloadResponse;
          if (preloaded) return preloaded;
          return await fetch(request);
        } catch {
          // Offline: show the branded shell rather than the browser's dino page.
          const cache = await caches.open(PRECACHE);
          const offline = await cache.match(OFFLINE_URL);
          return (
            offline ||
            new Response("<h1>You are offline</h1>", {
              status: 503,
              headers: { "Content-Type": "text/html; charset=utf-8" },
            })
          );
        }
      })(),
    );
    return;
  }

  if (isFont(request, url)) {
    event.respondWith(cacheFirst(request, FONT_CACHE).catch(() => fetch(request)));
    return;
  }

  if (isImage(request, url)) {
    event.respondWith(
      cacheFirst(request, IMAGE_CACHE, { limit: IMAGE_CACHE_LIMIT }).catch(() => fetch(request)),
    );
    return;
  }

  if (isStaticAsset(request, url)) {
    // Content-hashed build output is immutable, so cache-first is always safe.
    if (url.pathname.startsWith("/_next/static")) {
      event.respondWith(cacheFirst(request, STATIC_CACHE).catch(() => fetch(request)));
      return;
    }
    event.respondWith(staleWhileRevalidate(request, STATIC_CACHE));
  }
});
